CREATE     PROCEDURE [synapse_fo].[usp_Insert_INVENTITEMGROUP]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:51
	Description: Insert stored procedure for INVENTITEMGROUP from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[INVENTITEMGROUP]
	(
		[ASSETGROUP_IN],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DUEDATELIMITGROUPID_ES],
		--[FileName],
		[ITEMGROUPID],
		[LastProcessedChange_DateTime],
		[LOADTEMPLATEID],
		--[LSN],
		[MODIFIEDDATETIME],
		[NAME],
		[PARTITION],
		[RECID],
		[RECVERSION],
		[RETAILSAFTSTANDARDVATCODE],
		[REVRECDEFAULTREVENUERECOGNITIONSCHEDULE],
		[REVRECEXCLUDEFROMCARVEOUT],
		[REVRECMEDIANPRICE],
		[REVRECMEDIANPRICEMAXIMUMTOLERANCE],
		[REVRECMEDIANPRICEMINIMUMTOLERANCE],
		[REVRECREVENUERECOGNITIONENABLED],
		[REVRECREVENUETYPE],
		[STANDARDITEMALLOCATEID],
		--[SysRowId],
		[TAXITEMGROUPIDPURCH],
		[TAXITEMGROUPIDSALES]
	)
	SELECT 
		stg.[ASSETGROUP_IN],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DUEDATELIMITGROUPID_ES],
		--stg.--[FileName],
		stg.[ITEMGROUPID],
		stg.[LastProcessedChange_DateTime],
		stg.[LOADTEMPLATEID],
		--stg.--[LSN],
		stg.[MODIFIEDDATETIME],
		stg.[NAME],
		stg.[PARTITION],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[RETAILSAFTSTANDARDVATCODE],
		stg.[REVRECDEFAULTREVENUERECOGNITIONSCHEDULE],
		stg.[REVRECEXCLUDEFROMCARVEOUT],
		stg.[REVRECMEDIANPRICE],
		stg.[REVRECMEDIANPRICEMAXIMUMTOLERANCE],
		stg.[REVRECMEDIANPRICEMINIMUMTOLERANCE],
		stg.[REVRECREVENUERECOGNITIONENABLED],
		stg.[REVRECREVENUETYPE],
		stg.[STANDARDITEMALLOCATEID],
		--stg.--[SysRowId],
		stg.[TAXITEMGROUPIDPURCH],
		stg.[TAXITEMGROUPIDSALES]	
	FROM [staging_fo].[INVENTITEMGROUP] stg
		LEFT JOIN [synapse_fo].[INVENTITEMGROUP] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[ItemGroupId] = tgt.[ItemGroupId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
	WHERE tgt.[RECID] IS NULL
END
